-- Database Migration 033: Repair Null Tiny/Preview URLs
-- Generated by Antigravity Deep Dive (Phase 35.5)
-- 1. Repair tinyUrl (Converted to WebP)
-- Pattern: thumbnails are "_thumb.jpg", tiny are "_tiny.webp"
UPDATE photos
SET tinyUrl = REPLACE(
        REPLACE(
            REPLACE(thumbnailUrl, '_thumb.jpg', '_tiny.webp'),
            '_thumb.jpeg',
            '_tiny.webp'
        ),
        '_thumb.png',
        '_tiny.webp'
    )
WHERE (
        tinyUrl IS NULL
        OR tinyUrl = ''
    )
    AND thumbnailUrl IS NOT NULL
    AND thumbnailUrl LIKE '%_thumb%';
-- 2. Repair previewUrl (Same extension as original/thumbnail)
-- Pattern: thumbnails are "_thumb.jpg", previews are "_preview.jpg"
UPDATE photos
SET previewUrl = REPLACE(thumbnailUrl, '_thumb', '_preview')
WHERE (
        previewUrl IS NULL
        OR previewUrl = ''
    )
    AND thumbnailUrl IS NOT NULL
    AND thumbnailUrl LIKE '%_thumb%';